static int radius(const Obj*o){Obj copy=*o;ndraw=0;if(o->type==4)draw_stage_boss(fb,&copy,o->x/Q,o->y/Q);else if(o->type<5)pc_enemy_sprite(o->type==0?1:o->type+5,&copy,o->x/Q,o->y/Q);else draw_new_enemy(fb,&copy,o->x/Q,o->y/Q);float r=0;static const int wh[8][2]={{23,24},{30,34},{24,28},{24,28},{22,25},{26,30},{52,64},{24,36}};for(int i=0;i<ndraw;i++){Draw*d=draws+i;float w,h;if(d->n>=137){w=wh[d->n-137][0];h=wh[d->n-137][1];}else{w=modernSprites[d->n].w;h=modernSprites[d->n].h;}float size=hypotf(w,h)*.5f*(d->scale>0?d->scale:1);if(size>r)r=size;}return (int)ceilf(r);}
static int outside(int x,int y,int r){for(int dy=-r;dy<=r;dy+=3){float rx=sqrtf(fmaxf(0,r*r-dy*dy));int yy=y+dy,l=tunnel_left(yy),rr=tunnel_right(yy),il,ir;if(x-rx<l||x+rx>rr||(tunnel_island(yy,&il,&ir)&&x+rx>il&&x-rx<ir))return 1;}return 0;}
static void scene(int m,int section){headless=1;selectedShip=0;configuredLevel=1;game_reset();g.mode=1;g.fx=0;g.wave=m;ex.section=section;ex.phase=ex.oldPhase=mission_phase(m);ex.intro=ex.travel=ex.entryY=0;ex.phaseAge=100;ex.rearSpawned=1;ex.options=ex.optionsOn=0;g.clock=-100000;g.groups=0;g.shield=100000;environment_enter();}

int main(void){int contexts[6][2]={{2,1},{2,2},{3,2},{3,4},{4,2},{5,2}};float maxByType[29]={0};int bytype[29]={0},packed[29]={0};int bad=0,jumps=0,corrections=0,packing=0,samples=0;float maxCorrection=0;for(int c=0;c<6;c++)for(int type=0;type<29;type++){if(type==9||type==23||type==24)continue;scene(contexts[c][0],contexts[c][1]);ex.cavernWorldReady=1;ex.cavernWorldQ=(c*683)*Q;if(type==4){ex.bossSpawned=1;ex.encounterTier=1;Obj*o=g.enemies;*o=(Obj){.on=1,.type=4,.variant=12,.hp=100,.base=300,.phase=3,.power=512,.x=160*Q,.y=95*Q,.age=200};}else if(type==22)rear_group();else group(type,0);for(int t=0;t<900;t++){Obj prev[MAXE];memcpy(prev,g.enemies,sizeof(prev));g.shield=100000;game_step(0,0);for(int i=0;i<MAXE;i++){Obj*o=g.enemies+i;if(!o->on||floor_enemy(o))continue;samples++;if(outside(o->x/Q,o->y/Q,radius(o))){bad++;if(bad<25)printf("OUT c%d type%d t%d age%d x%d y%d r%d side%d\n",c,o->type,t,o->age,o->x/Q,o->y/Q,radius(o),o->caveSide);}if(prev[i].on&&prev[i].type==o->type&&o->age==prev[i].age+1&&o->y>0&&o->y<280*Q){float dx=absn(o->x-prev[i].x)/(float)Q;if(t>0&&dx>maxByType[o->type]){maxByType[o->type]=dx;if((o->type==10||o->type==11)&&dx>6)printf("BUGJUMP c%d type%d tick%d age%d x%d->%d y%d->%d giant%d add%d\n",c,o->type,t,o->age,prev[i].x/Q,o->x/Q,prev[i].y/Q,o->y/Q,ex.giant.active,o->reinforcement);}if(dx>6.1f&&!(o->type==18&&o->age%130==85)){jumps++;bytype[o->type]++;if(dx>maxCorrection){maxCorrection=dx;printf("MAXJUMP c%d type%d t%d age%d %.2f y%d\n",c,o->type,t,o->age,dx,o->y/Q);}}}if(o->y>0&&o->y<250*Q){int near=0;for(int j=0;j<MAXE;j++)if(j!=i&&g.enemies[j].on&&absn(o->x-g.enemies[j].x)<3*Q&&absn(o->y-g.enemies[j].y)<3*Q)near++;if(near>=3){packing++;packed[o->type]++;}}}}}for(int ty=0;ty<29;ty++)if(bytype[ty]||packed[ty])printf("TYPE %d jumps%d packing%d maxStep%.2f\n",ty,bytype[ty],packed[ty],maxByType[ty]);printf("MOTION samples%d outside%d jumps%d max%.2f packing%d hardClamp%.3f\n",samples,bad,jumps,maxCorrection,packing,cavernMaxSnap);for(int ty=0;ty<29;ty++)if(ty!=18&&maxByType[ty]>7)return 1;return bad?1:0;}
